await page.evaluate(() => {
  const el = document.querySelector('.target');
  const textColor = getComputedStyle(el).color;
  const bgColor = getComputedStyle(el).backgroundColor;
  // Parse RGB, linearize, compute luminance, compute ratio
  // Returns { ratio: 1.36, passesAA: false, passesAALarge: false }
});

await page.evaluate(() => {
  const elements = document.querySelectorAll('h1, h2, h3, h4, h5, h6, p, span, a, button, li, td, th, label, .badge, .status, [class*="card"], [class*="panel"]');
  return Array.from(elements).map(el => {
    const style = getComputedStyle(el);
    return {
      text: el.textContent.trim().substring(0, 60),
      tag: el.tagName,
      class: el.className.substring(0, 60),
      textColor: style.color,
      bgColor: style.backgroundColor,
      fontSize: style.fontSize,
      fontWeight: style.fontWeight,
      opacity: style.opacity,
    };
  });
});
